def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.2))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= budget:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (supply <= 17)
    abundance = (supply >= 22)
    critical_me = (hp <= 3 or no_water_days >= 1)
    weak_me = (hp <= 5)

    target = 0.0

    if critical_me:
        if highest_prev > 0:
            target = max(DAILY_SALARY * 1.25, highest_prev + 4.0)
        else:
            target = DAILY_SALARY * 1.1
        if scarcity:
            target += 10.0
    elif scarcity:
        if highest_prev >= 120:
            target = highest_prev + 2.0
        elif highest_prev > 0:
            target = max(DAILY_SALARY * 0.95, avg_prev + 8.0)
        else:
            target = DAILY_SALARY * 0.9
        if urgent_opp >= 2:
            target += 6.0
    elif abundance:
        if hp >= 7 and no_water_days == 0:
            target = DAILY_SALARY * 0.18
        else:
            target = DAILY_SALARY * 0.45
        if highest_prev >= 140:
            target = min(target, DAILY_SALARY * 0.25)
    else:
        if weak_me:
            if highest_prev >= 120:
                target = highest_prev + 1.0
            elif highest_prev > 0:
                target = max(DAILY_SALARY * 0.8, avg_prev + 5.0)
            else:
                target = DAILY_SALARY * 0.75
        else:
            if highest_prev >= 140:
                target = DAILY_SALARY * 0.28
            elif highest_prev >= 100:
                target = DAILY_SALARY * 0.52
            elif highest_prev > 0:
                target = max(DAILY_SALARY * 0.42, avg_prev * 0.72)
            else:
                target = DAILY_SALARY * 0.4

    if day >= 8:
        if hp >= 6 and no_water_days == 0 and not scarcity:
            target *= 0.85
        elif critical_me:
            target *= 1.08

    if rich_opp >= 2 and critical_me:
        target += 5.0

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 20.0
    elif day <= 9:
        reserve_floor = 5.0

    max_affordable = budget - reserve_floor
    if max_affordable < 0:
        max_affordable = budget

    bid = min(target, max_affordable)
    if critical_me:
        bid = min(target, budget)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append(o)
        except Exception:
            continue

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace only.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    # Determine how many daily units we can cover with one win.
    # In this game, water is consumed; typical clearing is around WATER_REQ.
    # We use supply to infer scarcity: lower supply -> higher clearing price.
    scarcity = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (float(MAX_SUPPLY) - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    # Target bid: slightly under the highest observed pressure to undercut,
    # but ramp up when our hp/no_water_days is critical or supply is scarce.
    critical = (my_hp <= 2) or (my_no_water_days >= 2)

    # Baseline depending on scarcity.
    base = DAILY_SALARY * (0.45 + 0.35 * scarcity)

    # If someone was bidding very high yesterday, we should not be too low,
    # else we risk losing water and dying.
    # Use highest_prev_bid as an upper pressure signal.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if critical:
            target = base + 0.25 * (highest_prev_bid - base)
        else:
            target = min(highest_prev_bid - 1.0, base + 0.15 * (highest_prev_bid - base))
    else:
        # When overall pressure was moderate, bid closer to average + small premium.
        if critical:
            target = max(base, avg_prev_bid * 0.9)
        else:
            target = min(max(base, avg_prev_bid * 0.75), avg_prev_bid + 10.0)

    # Clamp to budget and non-negative.
    target = max(0.0, float(target))
    bid = min(my_budget, target)

    # If budget is very low, still try to secure enough to survive.
    if my_budget < DAILY_SALARY * 0.2:
        bid = min(my_budget, DAILY_SALARY * 0.25)

    return float(bid)

